(async () => {
  const root = document.querySelector('[data-window-gallery]');
  if (!root) return {error: 'no root'};
  root.scrollIntoView();
  await new Promise(r => setTimeout(r, 6000));
  const canvas = root.querySelector('canvas');
  const gl = (() => { try { const c = document.createElement('canvas'); return !!(c.getContext('webgl2') || c.getContext('webgl')); } catch (e) { return false; } })();
  return {
    cls: root.className,
    canvas: !!canvas,
    canvasSize: canvas ? [canvas.width, canvas.height] : null,
    swatches: root.querySelectorAll('.wg__swatch').length,
    name: (root.querySelector('[data-wg-name]') || {}).textContent,
    webgl: gl,
    modules: [...document.querySelectorAll('script[type=module], link[rel=modulepreload]')].length
  };
})()
